	["Bordure blanche : votre cible"] = "White border: your target",
	["Cadre bleu : magie que vous pouvez dissiper"] = "Blue frame: magic you can dispel",
	["Cadre violet : malédiction"] = "Purple frame: curse", ["Cadre brun : maladie"] = "Brown frame: disease",
